INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5014, "", "wac_birthday_talk_sad", "", 0.2, 5014063, 1, 3, 100211, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5014, "", "vo_wac_05014_002", 0, "", 5014064, 0, 21, "vo_wac_05014", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5014, 0, "そ、そんな……わたしだって、いつも\n助けられてばっかりで……ご、ごめん！\nせっかくお祝いしてもらってるのに\nうれしくて泣いちゃいそう……！", 1, 0, 5014065, 10, 11, 100211, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5014, "", "", "", "", 5014066, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5014, "", "wac_birthday_talk_smile", "", 0.2, 5014067, 1, 3, 100211, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5014, "", "vo_wac_05014_003", 0, "", 5014068, 0, 21, "vo_wac_05014", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5014, 0, "騎士クンも、本当にありがとうね。\nみんなに祝福してもらえて\nわたし、最高に幸せだよ……！\n大事に味わって食べるね！", 1, 0, 5014069, 10, 11, 100211, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5014, "", "", "", "", 5014070, "", 91, 0, "", "");
