INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5214, "", "wac_birthday_talk_wish", "", 0.2, 5214074, 1, 3, 105511, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5214, "", "vo_wac_05214_002", 0, "", 5214075, 0, 21, "vo_wac_05214", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5214, 0, "え、えっと……\nこれ、夢じゃないですよね？\nほっぺをつねっても……いひゃい！\nやっぱり夢じゃないれす！", 1, 0, 5214076, 10, 11, 105511, 0.5, 1);
