INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (5514, 0, "わわ、これってうちの誕生日ケーキ？\nこんなのあるなんて聞いてないし～！\nオニ感激なんだけど！？", 1, 0, 5514055, 10, 11, 101611, 0.5, 1);
