INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (8014, 0, "おお、わらわの誕生日祝いか！\nうむうむ！　お主らも夜を統べるものの\n従者としての振る舞いを理解してきた\nようじゃのう！", 1, 0, 8014066, 10, 11, 104411, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (8014, "", "", "", "", 8014067, "", 91, 0, "", "");
