INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (13114, "", "vo_wac_13114_002", 0, "", 13114066, 0, 21, "vo_wac_13114", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (13114, 0, "イノリちゃんは彼が準備してるのを\nつまみ食いしながら\n見てただけじゃなかったっけ？", 1, 0, 13114067, 10, 11, 106711, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (13114, "", "", "", "", 13114068, "", 91, 0, "", "");
