INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (16614, 0, "誕生、日……？\n私のですか？\nなぜそんなことを\n覚えているのですか？", 1, 0, 16614068, 10, 11, 102711, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (16614, "", "", "", "", 16614069, "", 91, 0, "", "");
