INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (16614, 0, "………………そう、ですか。\nそれならありがたく\nいただくことにしましょう。", 1, 0, 16614078, 10, 11, 102711, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (16614, "", "", "", "", 16614079, "", 91, 0, "", "");
