INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (17714, "", "vo_wac_17714_003", 0, "", 17714071, 0, 21, "vo_wac_17714", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (17714, 0, "じつは、ミミたちだけじゃ運べなくて。\nおにいちゃんも手伝ってくれたの～♪", 1, 0, 17714072, 10, 11, 102011, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (17714, "", "", "", "", 17714073, "", 91, 0, "", "");
