INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (18114, 0, "イオちゃん、大げさだよ～\nでも、喜んでもらえたなら、\n手作りしてよかったかも♪", 1, 0, 18114063, 10, 11, 105011, 0.5, 1);
