INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (18114, 0, "ヒデサイにも買い出しとか\n手伝ってもらったしー\nみんなでお祝いする誕生日って、\nそれだけでエモいっしょ♪", 1, 0, 18114068, 10, 11, 101611, 0.5, 1);
