INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (19414, 0, "騎士クンとレイちゃん、\nみんなで手作りしたの♪\nお店で買った方がおいしいかもって、\nちょっと迷ったりもしたんだけど……", 1, 0, 19414063, 10, 11, 100211, 0.5, 1);
