INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (19414, 0, "ちゃんと、私たちの気持ちが\n伝わるような贈り物にしたかったんだ。\nだから、味の方はあまり期待しないで\nくれるかな？", 1, 0, 19414068, 10, 11, 100311, 0.5, 1);
