INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (19414, 0, "えへへ……本当に、ありがとう！\nなんだか食べる前から、\n胸のあたりがじ～んとしちゃうよ～♪\nよーし、さっそくわけちゃおー！", 1, 0, 19414073, 10, 11, 100111, 0.5, 1);
