INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (19814, 0, "誕生日にそんなことされて喜ぶのは、\nクウカさんだけだと思います……", 1, 0, 19814086, 10, 11, 105511, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (19814, "", "", "", "", 19814087, "", 91, 0, "", "");
