INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (19814, 0, "なんと、ショーグンまで！？\nみなさん、アリガトウゴザイマシタ！\nこの喜び、忍法で表現シマスよ～？\nシュバ、シュババ、シュバババ～♪", 1, 0, 19814101, 10, 11, 103011, 0.5, 1);
