INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (22014, 0, "ふふっ、にぎやかで、楽しくて、\n最高の誕生日になりそうやね。\n王子はんも、お祝いに来てくれて\nありがとうな～♪", 1, 0, 22014083, 10, 11, 101011, 0.5, 1);
