INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (22714, 0, "えっ、あっ、それは……！？\nここ、この度はあたしのお誕生日を\nお祝いしてくれやがりまして、まことに\nありがとうございますです！", 1, 0, 22714066, 10, 11, 106611, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (22714, "", "", "", "", 22714067, "", 91, 0, "", "");
