INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (22714, 0, "いや、どんな敬語だよ……\nでも、気持ちは伝わったかな？\nケーキ一つでこんなにご機嫌なんだ、\n来年もまた、用意してやりますか。", 1, 0, 22714071, 10, 11, 106511, 0.5, 1);
