INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (23214, 0, "今日は、本当にみんなありがとう。\nあたしの誕生日のために、こんなに\n素敵なケーキを用意してくれるなんてね♪", 1, 0, 23214063, 10, 11, 102811, 0.5, 1);
