INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (23214, 0, "頑張って手作りしたんだよ？\nできあがる頃には、いろんな意味で\nスズメはボロボロになってたけど。", 1, 0, 23214073, 10, 11, 102311, 0.5, 1);
