INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (23214, 0, "アヤネちゃん、それは内緒に……！\nうぅ、お料理中も結構ドジしちゃって。\nお嬢様の大切な日の準備なのに、\nすみません……", 1, 0, 23214078, 10, 11, 102511, 0.5, 1);
