INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (25314, 0, "そうだったのか。\nクリスちゃんも、みんなも、\n私なんかのためにありがとう。", 1, 0, 25314085, 10, 11, 104711, 0.5, 1);
