INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (25314, 0, "私なんかのために、\nなんて言わないでください。\nジュンさんのことが大好きだから、\n頑張って準備したんですよ♪", 1, 0, 25314090, 10, 11, 103711, 0.5, 1);
