INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (25314, 0, "ふふっ、そうだね、ごめん。\n【王宮騎士団（NIGHTMARE）】\nの団長で、私は幸せ者だ……こんなにも\n素敵な仲間に恵まれたのだから。", 1, 0, 25314095, 10, 11, 104711, 0.5, 1);
