INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (27014, 0, "最初に聞いた時は驚いたけれど。\n今日は私の誕生日を\nお祝いしてくれてありがとう♪\n素敵なケーキまで用意してくれて……", 1, 0, 27014063, 10, 11, 104811, 0.5, 1);
