INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (27014, 0, "か、乾杯前にデキあがってる人が……\nでも、これくらいにぎやかな方が、\n私たちらしいかもしれないわね。\nキミもそう思うでしょ？　ふふっ♪", 1, 0, 27014083, 10, 11, 104811, 0.5, 1);
