INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, 0, "わわっ、大きなケーキッス！\n……え、もしかして自分のッスかねっ？\n誕生日覚えてくれてたッスか？", 1, 0, 28414063, 10, 11, 100511, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "", "", "", 28414064, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "wac_birthday_idle_kyapi", "", 0.2, 28414065, 1, 3, 100511, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "wac_birthday_talk_smile", "", 0.2, 28414066, 1, 3, 103711, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "vo_wac_28414_001", 0, "", 28414067, 0, 21, "vo_wac_28414", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, 0, "もちろんだよ。\n誕生日おめでとう、マツリちゃん。\nこの間の予防注射もきちんと受けてたし\n大人にまた一歩近づいたね♪", 1, 0, 28414068, 10, 11, 103711, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "", "", "", 28414069, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "wac_birthday_idle_smile", "", 0.2, 28414070, 1, 3, 103711, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "wac_birthday_talk_wish", "", 0.2, 28414071, 1, 3, 104711, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "vo_wac_28414_002", 0, "", 28414072, 0, 21, "vo_wac_28414", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, 0, "おめでとう、マツリちゃん。\n私たちだけではなく、\n少年も一緒に準備してくれたんだよ。", 1, 0, 28414073, 10, 11, 104711, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "", "", "", 28414074, "", 91, 28414073, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "wac_birthday_idle_wish", "", 0.2, 28414075, 1, 3, 104711, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "wac_birthday_talk_doya", "", 0.2, 28414076, 1, 3, 107111, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "vo_wac_28414_003", 0, "", 28414077, 0, 21, "vo_wac_28414", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, 0, "ふふん、マツリちゃんもまた一歩、\nワタシに近づいたということだ。\n良かったな、これからも\nビシバシ鍛えてやるから期待していろ♪", 1, 0, 28414078, 10, 11, 107111, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (28414, "", "", "", "", 28414079, "", 91, 0, "", "");
