INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (29014, 0, "それじゃ、味わって食べなくちゃね！\nあなたも来てくれてありがとう！\nそうだ、みんなで記念の一枚を撮ろう！\n映写魔法を覚えたから、私に任せて♪", 1, 0, 29014073, 10, 11, 109211, 0.5, 1);
