INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (30314, 0, "そ、それはまた別の話でしょう！？\n私が言いたいのは……！", 1, 0, 30314085, 10, 11, 106411, 0.5, 1);
