INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31114, 0, "……ありがとうございます。\nわざわざ占ったりしませんが、\nこういう幸せな日々が、\nずっと続くことを願っています。", 1, 0, 31114100, 10, 11, 103111, 0.5, 1);
