INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31314, 0, "ハッピー☆バースデー☆ハツネちゃん！\nおっきなケーキまでもらっちゃって、\n最高の誕生日だよ～きらーんっ☆", 1, 0, 31314058, 10, 11, 101211, 0.5, 1);
