INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31714, 0, "そ、その……せっかくなら……\nあなたも一緒に、食べない……？\nあーん、ってしてあげたい、わ……", 1, 0, 31714062, 10, 11, 118111, 0.5, 1);
