INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (31714, 0, "主さまに「あーん」を……！？\nむぅ……仕方ありません。\n今日だけはお譲りしましょう。\n……一口だけでございますよ。", 1, 0, 31714067, 10, 11, 105911, 0.5, 1);
