INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, 0, "えっとさー、その～……\n普段あんまりお仕事してないのに、\nこんな大げさにお祝いされると\n気まずいっていうか～……", 1, 0, 32114065, 10, 11, 102611, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "", "", "", 32114066, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "wac_birthday_idle_normal", "", 0.2, 32114067, 1, 3, 102611, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "wac_birthday_talk_smile", "", 0.2, 32114068, 1, 3, 105211, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "vo_wac_32114_001", 0, "", 32114069, 0, 21, "vo_wac_32114", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, 0, "今さら気にするくらいなら、\n普段からしっかりやればいいのに。\n……なんてお小言はさておき、\nお誕生日おめでとう、リンちゃん♪", 1, 0, 32114070, 10, 11, 105211, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "", "", "", 32114071, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "wac_birthday_idle_smile", "", 0.2, 32114072, 1, 3, 105211, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "wac_birthday_talk_wish", "", 0.2, 32114073, 1, 3, 103811, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "vo_wac_32114_002", 0, "", 32114074, 0, 21, "vo_wac_32114", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, 0, "変に遠慮しないでくださいね？\nみんな、リンちゃんのことを\nお祝いしたくて、張り切って\n準備したんですから。", 1, 0, 32114075, 10, 11, 103811, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "", "", "", 32114076, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "wac_birthday_idle_wish", "", 0.2, 32114077, 1, 3, 103811, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "wac_birthday_talk_smile", "", 0.2, 32114078, 1, 3, 102611, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "vo_wac_32114_003", 0, "", 32114079, 0, 21, "vo_wac_32114", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, 0, "うぅ……そうだったんだね……\nここまでしてもらったんだから、\nあたしも心を入れ替えて、\n来年からはお仕事がんばるよ！", 1, 0, 32114080, 10, 11, 102611, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "", "", "", 32114081, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, "", "wac_birthday_idle_smile", "", 0.2, 32114082, 1, 3, 102611, "", "");
