INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32114, 0, "そう、来年から～\nというわけで今年も一年、\nぐうたらライフで平常運転\nしていくんで、よろしく～", 1, 0, 32114092, 10, 11, 102611, 0.5, 1);
