INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (32314, 0, "ほんとだ、なんかそれっぽい！\nえへへ、写真とか撮っちゃおうかな～♪\nアンタも一緒に入る？", 1, 0, 32314078, 10, 11, 105011, 0.5, 1);
