INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (33214, 0, "顔を真っ赤にしてるレイさんなんて\nなかなか見られないからね～\nほらほら、騎士くんもしっかり\n目に焼き付けておきなよ♪", 1, 0, 33214068, 10, 11, 100111, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (33214, "", "", "", "", 33214069, "", 91, 0, "", "");
