INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (33214, 0, "や、やめないかヒヨリ……！\nキミも真に受けて、じろじろ\n見るのはよしてくれ！\nますます変な顔になってしまう……！", 1, 0, 33214073, 10, 11, 100311, 0.5, 1);
