INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (34414, "", "wac_birthday_talk_smile", "", 0.2, 34414071, 1, 3, 102911, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (34414, "", "vo_wac_34414_003", 0, "", 34414072, 0, 21, "vo_wac_34414", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (34414, 0, "ツムギ、いいこと言うじゃない♪\nそれじゃあ感謝の気持ちを込めて……\nキミのためのバースデーライブ、\n開催しちゃおうかな♪", 1, 0, 34414073, 10, 11, 102911, 0.5, 1);
