INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (35514, 0, "うぅう～……\n甘めのケーキも、せんぱいたちも……\nあなたも、大好きですっ！！", 1, 0, 35514073, 10, 11, 109311, 0.5, 1);
