INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (35814, "", "vo_wac_35814_003", 0, "", 35814079, 0, 21, "vo_wac_35814", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (35814, 0, "なるほど、よく分かった。\nさては真面目に祝う気がないな？\n二人ともそこに並べ、ケーキの前に\nその無礼な舌先から切り分けてやろう☆", 1, 0, 35814080, 10, 11, 107111, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (35814, "", "", "", "", 35814081, "", 91, 0, "", "");
