INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (36914, 0, "ん？　何か特別な日だっただろうか？\n確かこの日がいいと言ったのは……\nキミだったか？", 1, 0, 36914085, 10, 11, 100311, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (36914, "", "", "", "", 36914086, "", 91, 0, "", "");
