INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "", "", "", 38214061, "", 131, 1, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "vo_wac_38214_000", 0, "", 38214062, 0, 21, "vo_wac_38214", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, 0, "みんな、今日はオラの誕生日を\n祝ってくれてあんがとな～♪\nそれで～……う～ん……！", 1, 0, 38214063, 10, 11, 103311, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", 1, "", "", 38214064, "", 93, 6, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_talk_sad", "", 0.2, 38214065, 1, 3, 103311, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "", "", "", 38214066, "", 91, 38214063, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_idle_sad", "", 0.2, 38214067, 1, 3, 103311, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_talk_sad", "", 0.2, 38214068, 1, 3, 103811, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "vo_wac_38214_001", 0, "", 38214069, 0, 21, "vo_wac_38214", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, 0, "マヒルさん、どうしました……？\nもしかして、誕生日ケーキに\n変なところでも……？", 1, 0, 38214070, 10, 11, 103811, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "", "", "", 38214071, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_idle_normal", "", 0.2, 38214072, 1, 3, 103811, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_talk_normal", "", 0.2, 38214073, 1, 3, 103311, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "vo_wac_38214_002", 0, "", 38214074, 0, 21, "vo_wac_38214", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, 0, "いや、そんなことねぇよ！？\n祝ってもらってすごくうれしいけんど、\nその気持ちをどんな素晴らしいギャグで\n表現すべきか悩んでんだべ……", 1, 0, 38214075, 10, 11, 103311, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "", "", "", 38214076, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_idle_normal", "", 0.2, 38214077, 1, 3, 103311, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_talk_smile", "", 0.2, 38214078, 1, 3, 102611, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "vo_wac_38214_003", 0, "", 38214079, 0, 21, "vo_wac_38214", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, 0, "いやいや、紛らわしすぎるから。\n普通のお礼で十分でしょ、\n深刻そうなオーラ醸さないでよね？", 1, 0, 38214080, 10, 11, 102611, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "", "", "", 38214081, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_idle_smile", "", 0.2, 38214082, 1, 3, 102611, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "wac_birthday_talk_smile", "", 0.2, 38214083, 1, 3, 105211, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "vo_wac_38214_004", 0, "", 38214084, 0, 21, "vo_wac_38214", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, 0, "そうそう。\n難しい顔するより、\nみんなで楽しくおいしくケーキを\n食べましょう♪", 1, 0, 38214085, 10, 11, 105211, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38214, "", "", "", "", 38214086, "", 91, 0, "", "");
