INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (38614, 0, "クスクス……安心してください。\n少なくともロウソクの数よりは、\nずっと若々しく見えていますわ……♪", 1, 0, 38614100, 10, 11, 102711, 0.5, 1);
