INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39114, "", "vo_wac_39114_003", 0, "", 39114077, 0, 21, "vo_wac_39114", "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39114, 0, "麦しゅわの助けも借りながら、\nみんなで協力して、\n全部乗り越えることができたもの！", 1, 0, 39114078, 10, 11, 103411, 0.5, 1);
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39114, "", "", "", "", 39114079, "", 91, 0, "", "");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39114, "", "wac_birthday_idle_doya", "", 0.2, 39114080, 1, 3, 103411, "", "");
