INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39314, 0, "リマリマには、いつも助けて\nもらってるからな～\nこういう時に、しっかり\nお返ししとかねぇと！", 1, 0, 39314068, 10, 11, 103311, 0.5, 1);
