INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39314, 0, "うんうん、ホントにね～\nリマのおかげで、\nあたしはぐうたらし放題な\nところあるしさ～", 1, 0, 39314073, 10, 11, 102611, 0.5, 1);
