INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39314, 0, "私も、病気がちで……\nリマさんにお仕事を代わって\nもらった日もありました。\nいつも、ありがとうございます……♪", 1, 0, 39314078, 10, 11, 103811, 0.5, 1);
