INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39514, 0, "うぅ……ぐすっ……ありがと～！！\nお誕生日を、こんなに、盛大に\nお祝いしてくれるなんて～！！", 1, 0, 39514063, 10, 11, 103411, 0.5, 1);
