INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (39514, 0, "さっきまでお礼のスピーチを\n考えてたらしいんだけど、\nいいアイデアが浮かばないからって、\n麦しゅわを飲んじゃったのよね……", 1, 0, 39514073, 10, 11, 104811, 0.5, 1);
