INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (40314, 0, "ネネカちゃんは、\n私の夢を叶えてくれた恩人ですもの。\nこれくらい、当然だわ♪\n彼も彼でお礼がしたかったみだいだし。", 1, 0, 40314053, 10, 11, 105211, 0.5, 1);
